{
  "story": "Merge sort divides the array into single elements and repeatedly merges sorted halves.",
  "aha": {
    "stateId": "merge",
    "observation": "Sub-arrays combine in sorted order, forming the final sorted sequence."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "target": "variant.states.calloutRegion"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "divide",
        "split",
        "merge"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Merge Sort",
        "regions": [
          {
            "id": "arr",
            "label": "Array",
            "kind": "array",
            "values": ["38", "27", "43", "3", "9", "82", "10"]
          }
        ],
        "states": [
          {
            "id": "divide",
            "label": "Initial",
            "short": "Start",
            "sentence": "Array is ready to be divided recursively.",
            "why": "Unsorted input data requires partitioning.",
            "active": ["arr"],
            "calloutRegion": "arr",
            "readouts": [
              {
                "id": "len",
                "label": "Length",
                "value": "7"
              }
            ]
          },
          {
            "id": "split",
            "label": "Split",
            "short": "Split",
            "sentence": "Elements are broken down to single units.",
            "why": "Base cases of size 1 are trivially sorted.",
            "active": ["arr"],
            "calloutRegion": "arr",
            "readouts": [
              {
                "id": "len",
                "label": "Depth",
                "value": "3"
              }
            ]
          },
          {
            "id": "merge",
            "label": "Merge",
            "short": "Merge",
            "sentence": "Sorted halves are merged back together.",
            "why": "Merging linear sequences maintains sorted order.",
            "active": ["arr"],
            "calloutRegion": "arr",
            "readouts": [
              {
                "id": "len",
                "label": "Status",
                "value": "Sorted"
              }
            ]
          }
        ]
      }
    ]
  }
}
